    AND t.id = #{bo.id}
    AND t.device_id = #{bo.deviceId}
    AND t.device_name LIKE CONCAT('%', #{bo.deviceName}, '%')
    AND t.device_type = #{bo.deviceType}
    AND t.line_id = #{bo.lineId}
    AND t.station_id = #{bo.stationId}
    AND t.param_name LIKE CONCAT('%', #{bo.paramName}, '%')
    AND t.unit = #{bo.unit}
    AND t.normal_value = #{bo.normalValue}
    AND t.abnormal_value = #{bo.abnormalValue}
    AND t.deviation_percent = #{bo.deviationPercent}
    AND t.monitor_status = #{bo.monitorStatus}
    AND t.event_time = #{bo.eventTime}
    AND t.exec_id = #{bo.execId}

ORDER BY t.id ASC
